88. /** Save the current game state. */
89. export function saveGame(
90.   player: PlayerState,
91.   defeatedBosses: Set<string>,
92.   codex: CodexData,
93.   appearanceId: string,
94.   timeStep: number = 0,
95.   weatherState?: WeatherState
96. ): void {
97.   const data: SaveData = {
98.     version: SAVE_VERSION,
99.     player,
100.     defeatedBosses: [...defeatedBosses],
101.     codex,
102.     appearanceId,
103.     timestamp: Date.now(),
104.     timeStep,
105.     weatherState,
106.   };
107.   try {
108.     localStorage.setItem(SAVE_KEY, JSON.stringify(data));
109.   } catch (error) {
110.     debugLog("[save] Failed to save", error);
111.   }
112. }
