136. function normalizeExploredTiles(value: unknown): Record<string, boolean> {
137.   if (!isRecord(value)) return {};
138.   const exploredTiles: Record<string, boolean> = {};
139.   for (const [key, explored] of Object.entries(value)) {
140.     if (explored === true) exploredTiles[key] = true;
141.   }
142.   return exploredTiles;
