145. function hashString(value: string): number {
146.   let hash = 2166136261;
147.   for (let index = 0; index < value.length; index++) {
148.     hash ^= value.charCodeAt(index);
149.     hash = Math.imul(hash, 16777619);
150.   }
151.   return hash >>> 0;
152. }
