154. function getInterimTrapSeed(
155.   player: PlayerState,
156.   layoutRecord: unknown,
157. ): number | undefined {
158.   if (!isRecord(layoutRecord)) return undefined;
159.   const optionId = layoutRecord["optionId"];
160.   if (typeof optionId === "string" && optionId.startsWith("layout:")) {
161.     const exactSeed = Number(optionId.slice("layout:".length));
162.     if (Number.isInteger(exactSeed) && exactSeed > 0) return exactSeed;
163.   }
164.   const naturalRoll = layoutRecord["naturalRoll"];
165.   const modifier = layoutRecord["modifier"];
166.   if (
167.     typeof naturalRoll !== "number"
168.     || !Number.isInteger(naturalRoll)
169.     || typeof modifier !== "number"
170.     || !Number.isInteger(modifier)
171.   ) {
172.     return undefined;
173.   }
174.   const appearance = player.customAppearance
175.     ? [
176.       player.customAppearance.skinColor,
177.       player.customAppearance.hairStyle,
178.       player.customAppearance.hairColor,
179.     ].join(":")
180.     : "default";
181.   return hashString([
182.     player.name,
183.     player.appearanceId,
184.     appearance,
185.     naturalRoll,
186.     modifier,
187.   ].join(":"));
188. }
