190. function getInterimTrapState(record: unknown): TrapState | undefined {
191.   if (!isRecord(record)) return undefined;
192.   const optionId = record["optionId"];
193.   const success = record["success"] === true;
194.   if (typeof optionId !== "string") return undefined;
195.   if (optionId.startsWith("triggered:")) return "triggered";
196.   if (optionId === "disarm") return success ? "disarmed" : "triggered";
197.   if (optionId === "detect") return success ? "detected" : "missed";
198.   return undefined;
199. }
