201. function migrateInterimTrapProgression(player: PlayerState): void {
202.   const progression = player.progression as unknown as Record<string, unknown>;
203.   const rawChecks = isRecord(progression["skillChecks"])
204.     ? progression["skillChecks"]
205.     : {};
206.   const existingSeed = progression["trapSeed"];
207.   if (
208.     !(typeof existingSeed === "number"
209.       && Number.isInteger(existingSeed)
210.       && existingSeed > 0)
211.   ) {
212.     const migratedSeed = getInterimTrapSeed(
213.       player,
214.       rawChecks["trap:layout"],
215.     );
216.     if (migratedSeed !== undefined) progression["trapSeed"] = migratedSeed;
217.   }
218. 
219.   const states = isRecord(progression["trapStates"])
220.     ? { ...progression["trapStates"] }
221.     : {};
222.   for (const [checkId, record] of Object.entries(rawChecks)) {
223.     if (!checkId.startsWith("trap:") || checkId === "trap:layout") continue;
224.     const trapId = checkId.slice("trap:".length);
225.     if (states[trapId] !== undefined) continue;
226.     const state = getInterimTrapState(record);
227.     if (state) states[trapId] = state;
228.   }
229.   progression["trapStates"] = states;
230. 
231.   const hadGuidanceItem = player.inventory.some(
232.     (item) => item.id === "adventurerTrapNotes",
233.   );
234.   if (hadGuidanceItem) {
235.     progression["trapGuidance"] = true;
236.     player.inventory = player.inventory.filter(
237.       (item) => item.id !== "adventurerTrapNotes",
238.     );
239.   }
240. 
241.   progression["skillChecks"] = Object.fromEntries(
242.     Object.entries(rawChecks).filter(([checkId]) => !checkId.startsWith("trap:")),
243.   );
244. }
