323.       const chunk = getCityChunk(city, position.cityChunkIndex);
324.       if (chunk && !isValidMapPosition(chunk.mapData, position.x, position.y)) {
325.         position.x = chunk.spawnX;
326.         position.y = chunk.spawnY;
327.       }
328.       return;
329.     }
330.     position.inCity = false;
331.     position.cityId = "";
332.     position.cityChunkIndex = 0;
333.   }
334. 
335.   position.chunkX = Math.min(Math.max(position.chunkX, 0), WORLD_WIDTH - 1);
336.   position.chunkY = Math.min(Math.max(position.chunkY, 0), WORLD_HEIGHT - 1);
337.   const terrain = getTerrainAt(
338.     position.chunkX,
339.     position.chunkY,
340.     position.x,
341.     position.y,
342.   );
343.   const wasSailing = player.progression.nautical.sailing;
344.   if (wasSailing && terrain === Terrain.Water) {
345.     const boat = player.progression.nautical.ownedBoats.find(
346.       (owned) => owned.id === player.progression.nautical.activeBoatId,
347.     );
348.     const sea = getSeaZoneAt(
349.       position.chunkX,
350.       position.chunkY,
351.       position.x,
352.       position.y,
353.     );
354.     if (
355.       boat
356.       && boat.condition > 0
357.       && sea
358.       && (sea.depth === "shallow" || getBoat(boat.id).deepWaterCapable)
359.     ) {
360.       return;
361.     }
362.     player.progression.nautical.sailing = false;
363.   }
364.   if (wasSailing && terrain !== Terrain.Water) {
365.     player.progression.nautical.sailing = false;
366.   }
367.   if (terrain === undefined || !isWalkable(terrain)) {
368.     if (wasSailing) {
369.       const discoveredPorts = player.progression.nautical.discoveredPortIds;
370.       const recoveryPortId =
371.         discoveredPorts[discoveredPorts.length - 1] ?? "sandportHarbor";
372.       const recoveryPort = getPort(recoveryPortId);
373.       position.chunkX = recoveryPort.location.chunkX;
374.       position.chunkY = recoveryPort.location.chunkY;
375.       position.x = recoveryPort.location.tileX;
376.       position.y = recoveryPort.location.tileY;
377.     } else {
378.       position.chunkX = 4;
379.       position.chunkY = 2;
380.       position.x = 3;
381.       position.y = 3;
382.     }
383.   }
384. }
