386. /** Load a saved game. Returns null if no save exists or it's corrupt. */
387. export function loadGame(): SaveData | null {
388.   try {
389.     const raw = localStorage.getItem(SAVE_KEY);
390.     if (!raw) return null;
391.     const parsed: unknown = JSON.parse(raw);
392.     if (!isRecord(parsed) || !isRecord(parsed["player"])) return null;
393.     if (typeof parsed["version"] !== "number") return null;
394.     const sourceVersion = parsed["version"];
395.     const data = parsed as unknown as SaveData;
396. 
397.     // Migration: old saves stored this field as "bestiary" — map to "codex"
398.     if (!data.codex && parsed["bestiary"]) {
399.       data.codex = parsed["bestiary"] as CodexData;
400.       delete parsed["bestiary"];
401.     }
402. 
403.     data.codex = normalizeCodexData(data.codex);
404.     data.appearanceId = readString(data.appearanceId, "knight");
405.     data.defeatedBosses = normalizeStringArray(data.defeatedBosses);
406.     data.player.knownAbilities = normalizeStringArray(data.player.knownAbilities);
407.     data.player.knownTalents = normalizeStringArray(data.player.knownTalents);
408. 
409.     const playerRecord = data.player as unknown as Record<string, unknown>;
410.     if (!isRecord(playerRecord["position"])) {
411.       data.player.position = {
412.         x: readInteger(playerRecord["x"], 3),
413.         y: readInteger(playerRecord["y"], 3),
414.         chunkX: readInteger(playerRecord["chunkX"], 4),
415.         chunkY: readInteger(playerRecord["chunkY"], 2),
416.         inDungeon: readBoolean(playerRecord["inDungeon"]),
417.         dungeonId: readString(playerRecord["dungeonId"]),
418.         dungeonLevel: readInteger(playerRecord["dungeonLevel"], 0),
419.         inCity: readBoolean(playerRecord["inCity"]),
420.         cityId: readString(playerRecord["cityId"]),
421.         cityChunkIndex: 0,
422.       };
423.       delete playerRecord["x"];
424.       delete playerRecord["y"];
425.       delete playerRecord["chunkX"];
426.       delete playerRecord["chunkY"];
427.       delete playerRecord["inDungeon"];
428.       delete playerRecord["dungeonId"];
429.       delete playerRecord["dungeonLevel"];
430.       delete playerRecord["inCity"];
431.       delete playerRecord["cityId"];
432.     }
433. 
434.     if (data.player.position.dungeonLevel === undefined) {
435.       data.player.position.dungeonLevel = 0;
436.     }
437.     if (data.player.position.cityChunkIndex === undefined) {
438.       data.player.position.cityChunkIndex = 0;
439.     }
440. 
441.     if (!isRecord(playerRecord["progression"])) {
442.       data.player.progression = {
443.         openedChests: normalizeStringArray(playerRecord["openedChests"]),
444.         collectedTreasures: normalizeStringArray(playerRecord["collectedTreasures"]),
445.         exploredTiles: normalizeExploredTiles(playerRecord["exploredTiles"]),
446.         discoveredCities: [],
447.         quests: normalizeQuestLog(playerRecord["quests"]),
448.         seenCutsceneIds: [],
449.         pendingCutsceneIds: [],
450.         skillChecks: {},
451.         trapSeed: LEGACY_TRAP_SEED,
452.         trapStates: {},
453.         trapGuidance: false,
454.         tutorial: normalizeTutorialProgress(undefined),
455.         worldEvents: normalizeWorldEventState(undefined),
456.         social: createSocialState(),
457.         achievements: normalizeAchievementState(undefined, sourceVersion),
458.         gathering: normalizeGatheringState(undefined, sourceVersion),
459.         crafting: normalizeCraftingState(undefined, sourceVersion),
460.         nautical: normalizeNauticalState(undefined, sourceVersion),
461.         discoveredFeatureIds: [],
462.         pendingFeatureRevealIds: [],
463.         debugDiscoveredFeatureIds: [],
464.         debugSuppressedFeatureIds: [],
465.       };
466.       delete playerRecord["openedChests"];
467.       delete playerRecord["collectedTreasures"];
468.       delete playerRecord["exploredTiles"];
469.     }
470. 
471.     data.player.progression.openedChests = normalizeStringArray(
472.       data.player.progression.openedChests,
473.     );
474.     data.player.progression.collectedTreasures = normalizeStringArray(
475.       data.player.progression.collectedTreasures,
476.     );
477.     data.player.progression.exploredTiles = normalizeExploredTiles(
478.       data.player.progression.exploredTiles,
479.     );
480.     migrateInterimTrapProgression(data.player);
481.     data.player.progression.quests = normalizeQuestLog(
482.       data.player.progression.quests,
483.     );
484.     data.player.progression.seenCutsceneIds = normalizeSeenCutsceneIds(
485.       data.player.progression.seenCutsceneIds,
486.     );
487.     data.player.progression.pendingCutsceneIds = normalizePendingCutsceneIds(
488.       data.player.progression.pendingCutsceneIds,
489.       data.player.progression.seenCutsceneIds,
490.     );
491.     data.player.progression.skillChecks = normalizeSkillCheckRecords(
492.       data.player.progression.skillChecks,
493.     );
494.     const trapSeed = normalizeTrapSeed(data.player.progression.trapSeed);
495.     data.player.progression.trapSeed = trapSeed.seed;
496.     data.player.progression.trapStates = trapSeed.valid
497.       ? normalizeTrapStates(data.player.progression.trapStates)
498.       : {};
499.     data.player.progression.trapGuidance = readBoolean(
500.       data.player.progression.trapGuidance,
501.     );
502.     const tutorialProgress = data.player.progression.tutorial;
503.     data.player.progression.tutorial = tutorialProgress === undefined
504.         && sourceVersion < TUTORIAL_SAVE_VERSION
505.       ? { completed: true }
506.       : normalizeTutorialProgress(tutorialProgress);
507.     data.player.progression.worldEvents = normalizeWorldEventState(
508.       data.player.progression.worldEvents,
509.     );
510.     data.player.progression.social = sourceVersion < 12
511.       ? createSocialState()
512.       : normalizeSocialState(data.player.progression.social);
513.     if (sourceVersion < 12) {
514.       data.player.progression.social.appliedSourceIds.push(
515.         ...getHistoricalQuestSocialSourceIds(data.player.progression.quests),
516.       );
517.     }
518.     data.player.progression.achievements = normalizeAchievementState(
519.       data.player.progression.achievements,
520.       sourceVersion,
521.     );
522.     data.player.progression.gathering = normalizeGatheringState(
523.       data.player.progression.gathering,
524.       sourceVersion,
525.     );
526.     data.player.progression.crafting = normalizeCraftingState(
527.       data.player.progression.crafting,
528.       sourceVersion,
529.     );
530.     data.player.progression.nautical = normalizeNauticalState(
531.       data.player.progression.nautical,
532.       sourceVersion,
533.     );
534.     const featureDiscovery = sourceVersion < 17
535.       ? normalizeFeatureDiscoveryProgress({})
536.       : normalizeFeatureDiscoveryProgress(data.player.progression);
537.     Object.assign(data.player.progression, featureDiscovery);
538.     data.player.party = normalizePartyState(playerRecord["party"]);
539.     synchronizeCompanionRecruitment(data.player);
540.     synchronizeNauticalQuestRewards(data.player);
541.     ensureLegacyCampaignEpilogueQueued(data.player);
542. 
543.     if (data.player.equippedShield === undefined) data.player.equippedShield = null;
544.     if (data.player.equippedOffHand === undefined) data.player.equippedOffHand = null;
545.     if (data.timeStep === undefined) data.timeStep = 0;
546.     if (!data.weatherState) data.weatherState = createWeatherState();
547.     // Backward compat: last town defaults to Willowdale
548.     if (data.player.lastTownX === undefined) data.player.lastTownX = 2;
549.     if (data.player.lastTownY === undefined) data.player.lastTownY = 2;
550.     if (data.player.lastTownChunkX === undefined) data.player.lastTownChunkX = 4;
551.     if (data.player.lastTownChunkY === undefined) data.player.lastTownChunkY = 2;
552.     if (data.player.bankBalance === undefined) data.player.bankBalance = 0;
553.     if (data.player.lastBankDay === undefined) data.player.lastBankDay = 0;
554.     // Backward compat: mount system
555.     if (data.player.mountId === undefined) data.player.mountId = "";
556.     if (data.player.shortRestsRemaining === undefined) data.player.shortRestsRemaining = 2;
557.     if (data.player.pendingLevelUps === undefined) data.player.pendingLevelUps = 0;
558.     data.player.activeEffects = normalizeActiveEffects(data.player.activeEffects);
559. 
560.     const p = data.player;
561.     if (p.equippedWeapon) {
562.       const match = p.inventory.find(i => i.id === p.equippedWeapon!.id && i.type === "weapon");
563.       if (match) p.equippedWeapon = match;
564.     }
565.     if (p.equippedOffHand) {
566.       const match = p.inventory.find(i => i.id === p.equippedOffHand!.id && i.type === "weapon");
567.       if (match) p.equippedOffHand = match;
568.     }
569.     if (p.equippedArmor) {
570.       const match = p.inventory.find(i => i.id === p.equippedArmor!.id && i.type === "armor");
571.       if (match) p.equippedArmor = match;
572.     }
573.     if (p.equippedShield) {
574.       const match = p.inventory.find(i => i.id === p.equippedShield!.id && i.type === "shield");
575.       if (match) p.equippedShield = match;
576.     }
577. 
578.     const validCityIds = new Set(CITIES.map((city) => city.id));
579.     if (!Array.isArray(data.player.progression.discoveredCities)) {
580.       const ids = new Set<string>();
581.       for (const key of Object.keys(data.player.progression.exploredTiles)) {
582.         if (key.startsWith("c:")) {
583.           const cityId = key.split(",")[0].substring(2);
584.           if (validCityIds.has(cityId)) ids.add(cityId);
585.         }
586.       }
587.       data.player.progression.discoveredCities = [...ids];
588.     } else {
589.       data.player.progression.discoveredCities = [
590.         ...new Set(
591.           data.player.progression.discoveredCities.filter((cityId) =>
592.             typeof cityId === "string" && validCityIds.has(cityId)
593.           ),
594.         ),
595.       ];
596.     }
597. 
598.     normalizePlayerLocation(data.player);
599.     replayCodexUnlocks(data.codex, data.player);
600.     reconcileCraftingRecipes(data.player, data.codex);
601.     reconcileAchievements({
602.       player: data.player,
603.       defeatedBosses: new Set(data.defeatedBosses),
604.       codex: data.codex,
605.     }, {
606.       sourceId: sourceVersion < SAVE_VERSION
607.         ? `migration:v${sourceVersion}:v${SAVE_VERSION}`
608.         : "load:reconcile",
609.       unlockedAt: readInteger(data.timestamp, Date.now()),
610.       notify: false,
611.     });
612.     reconcileFeatureDiscovery(data.player, data.codex, { silent: true });
613.     data.version = SAVE_VERSION;
614.     return data;
615.   } catch (error) {
616.     debugLog("[save] Failed to load save", error);
617.     return null;
618.   }
619. }
