621. /** Check if a save exists. */
622. export function hasSave(): boolean {
623.   return loadGame() !== null;
624. }
625. 
626. /** Delete the save. */
627. export function deleteSave(): void {
628.   try {
629.     localStorage.removeItem(SAVE_KEY);
630.   } catch (error) {
631.     debugLog("[save] Failed to delete save", error);
632.   }
633. }
