635. /** Get a brief summary of the save for the title screen. */
636. export function getSaveSummary(): string | null {
637.   const data = loadGame();
638.   if (!data) return null;
639.   const p = data.player;
640.   const date = new Date(data.timestamp);
641.   const dateStr = `${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${String(date.getMinutes()).padStart(2, "0")}`;
642.   return `${p.name} Lv.${p.level} | HP ${p.hp}/${p.maxHp} | Gold ${p.gold} | ${dateStr}`;
643. }
