3279.   private terrainToBiome(terrain?: Terrain): string {
3280.     if (this.player.position.inDungeon) return "dungeon";
3281.     if (this.player.progression.nautical.sailing) return "sea";
3282.     if (this.player.position.inCity) return "city";
3283.     switch (terrain) {
3284.       case Terrain.Forest: return "forest";
3285.       case Terrain.DeepForest: return "deep_forest";
3286.       case Terrain.Sand: case Terrain.Cactus: return "sand";
3287.       case Terrain.Tundra: return "tundra";
3288.       case Terrain.Swamp: case Terrain.Mushroom: return "swamp";
3289.       case Terrain.Volcanic: case Terrain.Geyser: return "volcanic";
3290.       case Terrain.Canyon: return "canyon";
3291.       case Terrain.Water: case Terrain.River: return "sea";
3292.       default: return "grass";
3293.     }
