263. export class InputKeyOwnership {
264.   private readonly heldKeys = new Map<string, string>();
265.   private readonly ownerCounts = new Map<string, number>();
266. 
267.   acquire(token: string, key: string): boolean {
268.     if (this.heldKeys.has(token)) return false;
269.     this.heldKeys.set(token, key);
270.     const owners = this.ownerCounts.get(key) ?? 0;
271.     this.ownerCounts.set(key, owners + 1);
272.     return owners === 0;
273.   }
274. 
275.   release(token: string): { key: string; finalOwner: boolean } | null {
276.     const key = this.heldKeys.get(token);
277.     if (!key) return null;
278.     this.heldKeys.delete(token);
279.     const owners = this.ownerCounts.get(key) ?? 1;
280.     if (owners <= 1) {
281.       this.ownerCounts.delete(key);
282.       return { key, finalOwner: true };
283.     }
284.     this.ownerCounts.set(key, owners - 1);
285.     return { key, finalOwner: false };
286.   }
287. 
288.   clear(): string[] {
289.     const keys = [...this.ownerCounts.keys()];
290.     this.heldKeys.clear();
291.     this.ownerCounts.clear();
292.     return keys;
293.   }
294. }
