+const decode = (raw: string): { value: number } | null => {
+  const parsed: unknown = JSON.parse(raw);
+  if (
+    typeof parsed !== "object"
+    || parsed === null
+    || !("value" in parsed)
+    || typeof parsed.value !== "number"
+  ) {
+    return null;
+  }
+  return { value: parsed.value };
+};
