19. export interface SaveKeyValueStorage {
20.   getItem(key: string): string | null;
21.   setItem(key: string, value: string): void;
22.   removeItem(key: string): void;
23. }
24. 
25. export type SaveStorageErrorCode =
26.   | "missing"
27.   | "corrupt"
28.   | "invalid"
29.   | "quota"
30.   | "unavailable"
31.   | "verification";
32. 
33. export interface SaveStorageError {
34.   code: SaveStorageErrorCode;
35.   message: string;
36. }
37. 
38. export type SaveStorageWriteResult =
39.   | { ok: true }
40.   | { ok: false; error: SaveStorageError; previousValuePreserved: boolean };
41. 
42. export type SaveStorageReadResult<T> =
43.   | {
44.     ok: true;
45.     value: T;
46.     raw: string;
47.     source: "primary" | "staging" | "backup";
48.     recovered: boolean;
49.     recoveryError?: SaveStorageError;
50.   }
51.   | {
52.     ok: false;
53.     error: SaveStorageError;
54.     present: boolean;
55.   };
56. 
57. export function isSaveSlotId(value: unknown): value is SaveSlotId {
58.   return typeof value === "string"
59.     && (SAVE_SLOT_IDS as readonly string[]).includes(value);
60. }
