84. function slotDisplayName(
85.   slotId: SaveSlotId,
86.   storedName?: string | null,
87. ): string {
88.   if (slotId === "autosave") return "Autosave";
89.   if (storedName?.trim()) return storedName.trim();
90.   return `Manual ${Number(slotId.slice("manual-".length))}`;
