93. function deriveCampaignStatus(data: SaveData): SaveCampaignStatus {
94.   if (isQuestCompleted(data.player.progression.quests, MAIN_QUEST_ID)) {
95.     return data.player.progression.seenCutsceneIds.includes(
96.       CAMPAIGN_EPILOGUE_CUTSCENE_ID,
97.     )
98.       ? "Post-game"
99.       : "Complete";
100.   }
101.   const mainQuest = data.player.progression.quests.quests[MAIN_QUEST_ID];
102.   const hasProgress = (mainQuest?.stage ?? 0) > 0
103.     || Object.values(mainQuest?.objectives ?? {}).some((value) => value > 0);
104.   return hasProgress ? "In progress" : "Prologue";
105. }
