130. function deriveSlotMetadata(
131.   slotId: SaveSlotId,
132.   slotName: string,
133.   data: SaveData,
134. ): SaveSlotMetadata {
135.   const playerClass = getPlayerClass(data.player.appearanceId);
136.   return {
137.     slotId,
138.     slotName,
139.     characterName: data.player.name,
140.     classId: playerClass.id,
141.     className: playerClass.label,
142.     level: data.player.level,
143.     location: deriveSaveLocation(data.player),
144.     campaignStatus: deriveCampaignStatus(data),
145.     schemaVersion: data.version,
146.     savedAt: data.timestamp,
147.     playtimeSeconds: data.playtimeSeconds,
148.   };
149. }
