151. function getSlotInfo(
152.   slotId: SaveSlotId,
153.   adapter: SaveSlotStorageAdapter,
154. ): SaveSlotInfo {
155.   const displayName = slotDisplayName(slotId, adapter.getName(slotId));
156.   const result = adapter.read(slotId, decodeStoredSave);
157.   if (!result.ok) {
158.     return {
159.       slotId,
160.       kind: slotId === "autosave" ? "autosave" : "manual",
161.       state: result.error.code === "missing"
162.         ? "empty"
163.         : result.error.code === "corrupt"
164.           ? "corrupt"
165.           : "unavailable",
166.       displayName,
167.       ...(result.error.code === "missing"
168.         ? {}
169.         : { diagnostic: result.error.message }),
170.     };
171.   }
172.   if (result.recoveryError) {
173.     debugLog(`[save] ${result.recoveryError.message}`);
174.   } else if (result.recovered) {
175.     debugLog(`[save] Recovered ${slotId} from ${result.source}.`);
176.   }
177.   return {
178.     slotId,
179.     kind: slotId === "autosave" ? "autosave" : "manual",
180.     state: "valid",
181.     displayName,
182.     metadata: deriveSlotMetadata(slotId, displayName, result.value),
183.     recovered: result.recovered,
184.     ...(result.recoveryError
185.       ? { diagnostic: result.recoveryError.message }
186.       : {}),
187.   };
188. }
