190. function normalizeSlotName(name: string): string | null {
191.   const normalized = name
192.     .replace(/[\u0000-\u001f\u007f]/g, "")
193.     .replace(/\s+/g, " ")
194.     .trim()
195.     .slice(0, MAX_SLOT_NAME_LENGTH);
196.   return normalized.length > 0 ? normalized : null;
197. }
