247. /** List autosave and every manual slot without changing the active campaign. */
248. export function listSaveSlots(): SaveSlotInfo[] {
249.   const adapter = getStorageAdapter();
250.   if (!adapter || typeof localStorage === "undefined") {
251.     return SAVE_SLOT_IDS.map((slotId) => ({
252.       slotId,
253.       kind: slotId === "autosave" ? "autosave" : "manual",
254.       state: "unavailable",
255.       displayName: slotDisplayName(slotId),
256.       diagnostic: "Local campaign storage is unavailable.",
257.     }));
258.   }
259.   ensureSaveStorageMigrated(localStorage, adapter);
260.   return SAVE_SLOT_IDS.map((slotId) => getSlotInfo(slotId, adapter));
261. }
