263. /** Rename one manual slot without rewriting its campaign payload. */
264. export function renameSaveSlot(
265.   slotId: SaveSlotId,
266.   name: string,
267. ): SaveActionResult {
268.   if (slotId === "autosave") {
269.     return reportSaveFailure(
270.       "unsupported",
271.       "The Autosave slot cannot be renamed.",
272.     );
273.   }
274.   const normalized = normalizeSlotName(name);
275.   if (!normalized) {
276.     return reportSaveFailure("invalid-name", "Enter a non-empty slot name.");
277.   }
278.   const adapter = getStorageAdapter();
279.   if (!adapter) {
280.     return reportSaveFailure(
281.       "unavailable",
282.       "Local campaign storage is unavailable.",
283.     );
284.   }
285.   const slot = adapter.read(slotId, decodeStoredSave);
286.   if (!slot.ok) {
287.     return reportSaveFailure(
288.       slot.error.code === "missing" ? "not-found" : slot.error.code,
289.       slot.error.message,
290.     );
291.   }
292.   const result = adapter.setName(slotId, normalized);
293.   return result.ok
294.     ? { ok: true, message: `Renamed ${slotId} to ${normalized}.` }
295.     : reportSaveFailure(result.error.code, result.error.message);
296. }
