298. /** Copy one independent campaign snapshot into another stable slot. */
299. export function copySaveSlot(
300.   sourceSlotId: SaveSlotId,
301.   targetSlotId: SaveSlotId,
302.   overwrite = false,
303. ): SaveActionResult {
304.   if (sourceSlotId === targetSlotId) {
305.     return reportSaveFailure(
306.       "invalid",
307.       "Choose a different destination slot.",
308.     );
309.   }
310.   const source = readSaveSlotData(sourceSlotId);
311.   if (!source) {
312.     return reportSaveFailure(
313.       "not-found",
314.       `${sourceSlotId} has no valid campaign.`,
315.     );
316.   }
317.   source.timestamp = Date.now();
318.   const adapter = getStorageAdapter();
319.   const result = persistSaveData(targetSlotId, source, overwrite);
320.   if (!result.ok || targetSlotId === "autosave" || !adapter) return result;
321.   const sourceName = adapter.getName(sourceSlotId);
322.   const name = normalizeSlotName(
323.     sourceName ? `Copy of ${sourceName}` : `Copy of ${source.player.name}`,
324.   ) ?? source.player.name;
325.   const named = adapter.setName(targetSlotId, name);
326.   if (!named.ok) {
327.     return {
328.       ok: true,
329.       message: result.message,
330.       warning: `Campaign copied, but naming failed: ${named.error.message}`,
331.     };
332.   }
333.   return {
334.     ok: true,
335.     message: `Copied ${source.player.name} to ${slotDisplayName(targetSlotId, name)}.`,
336.   };
337. }
