356. /** Export one validated slot as deterministic, standalone JSON. */
357. export function exportSaveSlot(slotId: SaveSlotId): SaveExportResult {
358.   const data = readSaveSlotData(slotId);
359.   if (!data) {
360.     return {
361.       ok: false,
362.       code: "not-found",
363.       message: `${slotDisplayName(slotId)} has no valid campaign to export.`,
364.     };
365.   }
366.   const adapter = getStorageAdapter();
367.   const name = slotDisplayName(slotId, adapter?.getName(slotId));
368.   const document = canonicalizeJson({
369.     format: SAVE_EXPORT_FORMAT,
370.     formatVersion: SAVE_EXPORT_VERSION,
371.     name,
372.     save: data,
373.   });
374.   const safeName = name.toLowerCase().replace(/[^a-z0-9]+/g, "-")
375.     .replace(/^-|-$/g, "") || slotId;
376.   return {
377.     ok: true,
378.     fileName: `2dnd-${safeName}.json`,
