389.   private getActions(slot: SaveSlotInfo): SaveSlotAction[] {
390.     if (this.pendingConfirmation) return ["confirm", "cancel"];
391.     if (this.copySourceSlotId) return ["confirm", "cancel"];
392. 
393.     const actions: SaveSlotAction[] = [];
394.     if (this.mode === "load" && slot.state === "valid") actions.push("load");
395.     if (this.mode === "save" && slot.kind === "manual") actions.push("save");
396.     if (slot.kind === "manual" && slot.state === "valid") actions.push("rename");
397.     if (slot.state === "valid") actions.push("copy", "export");
398.     if (
399.       slot.state !== "empty"
400.       && (this.mode === "load" || slot.kind === "manual")
401.     ) {
402.       actions.push("delete");
403.     }
404.     if (this.mode === "load" || slot.kind === "manual") actions.push("import");
405.     actions.push("close");
406.     return actions;
407.   }
