413.       }
414.       return `${ACTION_LABELS[this.pendingConfirmation.kind]} will replace or remove stored data.`;
415.     }
416.     if (this.copySourceSlotId) {
417.       return slot.slotId === this.copySourceSlotId
418.         ? "Choose a different manual slot."
419.         : `Copy into ${slot.displayName}. Existing data requires confirmation.`;
420.     }
