424.   private readonly handleKeyDown = (event: KeyboardEvent): void => {
425.     if (!this.container) return;
426.     const handledAt = event.timeStamp || performance.now();
427.     if (
428.       event.repeat
429.       || (
430.         event.key === this.lastHandledKey
431.         && handledAt - this.lastHandledAt < 80
432.       )
433.     ) {
434.       return;
435.     }
436.     this.lastHandledKey = event.key;
437.     this.lastHandledAt = handledAt;
438.     if (event.key === "Escape") {
439.       event.preventDefault();
440.       event.stopImmediatePropagation();
441.       this.cancelOrClose();
442.       return;
443.     }
444.     if (
445.       event.key === "ArrowUp"
446.       || event.key === "w"
447.       || event.key === "W"
448.     ) {
449.       event.preventDefault();
450.       this.moveSlot(-1);
451.       return;
452.     }
453.     if (
454.       event.key === "ArrowDown"
455.       || event.key === "s"
456.       || event.key === "S"
457.     ) {
458.       event.preventDefault();
459.       this.moveSlot(1);
460.       return;
461.     }
462.     if (
463.       event.key === "ArrowLeft"
464.       || event.key === "a"
465.       || event.key === "A"
466.     ) {
467.       event.preventDefault();
468.       this.moveAction(-1);
469.       return;
470.     }

470.     }
471.     if (
472.       event.key === "ArrowRight"
473.       || event.key === "d"
474.       || event.key === "D"
475.     ) {
476.       event.preventDefault();
477.       this.moveAction(1);
478.       return;
479.     }
480.     if (event.key === "Home" || event.key === "End") {
481.       event.preventDefault();
482.       this.selectedSlotIndex = event.key === "Home" ? 0 : this.slots.length - 1;
483.       this.selectedActionIndex = 0;
484.       this.render();
485.       return;
486.     }
487.     if (event.key !== "Enter" && event.key !== " ") return;
488.     event.preventDefault();
489.     event.stopImmediatePropagation();
490.     this.activateSelectedAction();
491.   };
