493.   private moveSlot(direction: -1 | 1): void {
494.     const selectable = this.copySourceSlotId
495.       ? this.slots
496.         .map((slot, index) => ({ slot, index }))
497.         .filter(({ slot }) =>
498.           slot.kind === "manual" && slot.slotId !== this.copySourceSlotId
499.         )
500.       : this.slots.map((slot, index) => ({ slot, index }));
501.     if (selectable.length === 0) return;
502.     const current = selectable.findIndex(
503.       ({ index }) => index === this.selectedSlotIndex,
504.     );
505.     const next = (Math.max(current, 0) + direction + selectable.length)
506.       % selectable.length;
507.     this.selectedSlotIndex = selectable[next]!.index;
508.     this.selectedActionIndex = 0;
509.     this.status = "";
510.     this.render();
511.   }
