521.   private activateSelectedAction(): void {
522.     const action = this.actions[this.selectedActionIndex];
523.     const slot = this.slots[this.selectedSlotIndex];
524.     if (!action || !slot) return;
525. 
526.     if (action === "close") {
527.       this.close();
528.       return;
529.     }
530.     if (action === "cancel") {
531.       this.cancelPendingAction();
532.       return;
533.     }
534.     if (action === "confirm") {
535.       this.confirmPendingAction(slot);
536.       return;
537.     }
538.     if (action === "load") {
539.       this.close();
540.       this.callbacks.load(slot.slotId);
541.       return;
542.     }
543.     if (action === "save") {
544.       if (slot.state === "empty") {
545.         this.applyResult(this.callbacks.save(slot.slotId, false));
546.       } else {
547.         this.requestConfirmation({ kind: "save", targetSlotId: slot.slotId });
548.       }
549.       return;
550.     }
551.     if (action === "rename") {
552.       openMobileTextInput(
553.         "Save slot name",
554.         slot.displayName,
555.         24,
556.         (name) => this.applyResult(renameSaveSlot(slot.slotId, name)),
557.       );
558.       return;
559.     }
560.     if (action === "copy") {
561.       this.copySourceSlotId = slot.slotId;
562.       const target = this.slots.findIndex((candidate) =>
563.         candidate.kind === "manual" && candidate.slotId !== slot.slotId
564.       );
565.       this.selectedSlotIndex = Math.max(0, target);
566.       this.selectedActionIndex = 0;
567.       this.status = "";
568.       this.render();
569.       return;
570.     }
571.     if (action === "delete") {
572.       this.requestConfirmation({ kind: "delete", targetSlotId: slot.slotId });
573.       return;
574.     }
575.     if (action === "export") {
576.       this.exportSlot(slot.slotId);
577.       return;
578.     }
579.     if (action === "import") {
580.       if (slot.state === "empty") {
581.         this.openImportPicker(slot.slotId, false);
582.       } else {
583.         this.requestConfirmation({ kind: "import", targetSlotId: slot.slotId });
584.       }
585.     }
586.   }
