588.   private confirmPendingAction(selectedSlot: SaveSlotInfo): void {
589.     if (this.copySourceSlotId && !this.pendingConfirmation) {
590.       if (
591.         selectedSlot.kind !== "manual"
592.         || selectedSlot.slotId === this.copySourceSlotId
593.       ) {
594.         this.setStatus("Choose a different manual destination.", false);
595.         return;
596.       }
597.       if (selectedSlot.state === "empty") {
598.         const sourceSlotId = this.copySourceSlotId;
599.         this.copySourceSlotId = null;
600.         this.applyResult(copySaveSlot(sourceSlotId, selectedSlot.slotId));
601.       } else {
602.         this.requestConfirmation({
603.           kind: "copy",
604.           sourceSlotId: this.copySourceSlotId,
605.           targetSlotId: selectedSlot.slotId,
606.         });
607.       }
608.       return;
609.     }
610. 
611.     const pending = this.pendingConfirmation;
612.     if (!pending) return;
613.     this.pendingConfirmation = null;
614.     if (pending.kind === "newGame") {
615.       const start = this.startNewGame;
616.       this.close();
617.       start?.();
618.     } else if (pending.kind === "save") {
619.       this.applyResult(this.callbacks.save(pending.targetSlotId, true));
620.     } else if (pending.kind === "delete") {
621.       this.applyResult(deleteSave(pending.targetSlotId));
622.     } else if (pending.kind === "import") {
623.       this.openImportPicker(pending.targetSlotId, true);
624.     } else if (pending.sourceSlotId) {
625.       this.copySourceSlotId = null;
626.       this.applyResult(copySaveSlot(
627.         pending.sourceSlotId,
628.         pending.targetSlotId,
629.         true,
630.       ));
631.     }
632.   }
