682.   private exportSlot(slotId: SaveSlotId): void {
683.     const result = exportSaveSlot(slotId);
684.     if (!result.ok) {
685.       this.setStatus(result.message, false);
686.       return;
687.     }
688.     try {
689.       const url = URL.createObjectURL(new Blob([result.json], {
690.         type: "application/json",
691.       }));
692.       const link = document.createElement("a");
693.       link.href = url;
694.       link.download = result.fileName;
695.       link.click();
696.       URL.revokeObjectURL(url);
697.       this.setStatus(`Exported ${result.fileName}.`, true);
698.     } catch (error: unknown) {
699.       this.setStatus(`Export failed: ${String(error)}`, false);
700.     }
701.   }
