703.   private openImportPicker(slotId: SaveSlotId, overwrite: boolean): void {
704.     this.importInput?.remove();
705.     const input = document.createElement("input");
706.     input.id = "save-slot-import-input";
707.     input.type = "file";
708.     input.accept = ".json,application/json";
709.     input.setAttribute("aria-label", `Import campaign into ${slotId}`);
710.     input.style.position = "fixed";
711.     input.style.left = "-10000px";
712.     input.addEventListener("change", async () => {
713.       const file = input.files?.[0];
714.       if (!file) return;
715.       try {
716.         this.applyResult(importSaveSlot(slotId, await file.text(), overwrite));
717.       } catch (error: unknown) {
718.         this.setStatus(`Import failed: ${String(error)}`, false);
719.       } finally {
720.         input.remove();
721.         if (this.importInput === input) this.importInput = null;
722.       }
723.     }, { once: true });
724.     document.body.append(input);
725.     this.importInput = input;
726.     input.click();
727.   }
