import { expect, test, type Page } from "@playwright/test";

async function waitForState(page: Page, text: string): Promise<void> {
  await expect(page.locator("#debug-state")).toContainText(text);
}

test("SPACE closing the Overworld save menu leaks a world action", async ({
  page,
}) => {
  await page.addInitScript(() => {
    localStorage.clear();
  });
  await page.goto("game.html", { waitUntil: "networkidle" });

  // Seed an autosave where the hero stands on the Heartlands Crypt exit tile.
  await page.evaluate(async () => {
    const save = await import("/2dnd/src/systems/save.ts");
    const player = await import("/2dnd/src/systems/player.ts");
    const codex = await import("/2dnd/src/systems/codex.ts");
    const weather = await import("/2dnd/src/systems/weather.ts");
    const stats = {
      strength: 10, dexterity: 10, constitution: 10,
      intelligence: 10, wisdom: 10, charisma: 10,
    };
    save.deleteAllSaveSlots();
    const hero = player.createPlayer("Exit Hero", stats, "knight");
    hero.progression.pendingCutsceneIds = [];
    hero.progression.pendingFeatureRevealIds = [];
    hero.progression.tutorial.completed = true;
    hero.position.inDungeon = true;
    hero.position.dungeonId = "heartlands_dungeon";
    hero.position.dungeonLevel = 0;
    hero.position.x = 1;
    hero.position.y = 13;
    save.saveGame(
      hero, new Set(), codex.createCodex(), hero.appearanceId, 0,
      weather.createWeatherState(),
    );
  });

  await page.reload({ waitUntil: "networkidle" });
  await waitForState(page, "BOOT | Screen: title");
  await page.keyboard.press("Space");
  await waitForState(page, "OVERWORLD");
  await waitForState(page, "[DUNGEON:heartlands_dungeon]");

  // Open the escape menu and select "Save Game".
  await page.keyboard.press("Escape");
  await waitForState(page, "[MENU]");
  for (let i = 0; i < 12; i += 1) {
    const state = await page.locator("#debug-state").textContent() ?? "";
    if (state.includes("[MENU_SELECTION:save]")) break;
    await page.keyboard.press("ArrowDown");
    await page.waitForTimeout(80);
  }
  await waitForState(page, "[MENU_SELECTION:save]");
  await page.keyboard.press("Enter");
  await waitForState(page, "[SAVE_SLOTS:save]");

  // Navigate to the "close" action and press SPACE to dismiss the overlay.
  for (let i = 0; i < 8; i += 1) {
    const state = await page.locator("#debug-state").textContent() ?? "";
    if (state.includes("[SAVE_ACTION:close]")) break;
    await page.keyboard.press("ArrowRight");
    await page.waitForTimeout(80);
  }
  await waitForState(page, "[SAVE_ACTION:close]");
  await page.keyboard.press("Space");

  // Overlay must be gone.
  await expect(page.locator("#debug-state")).not.toContainText("[SAVE_SLOTS:");
  await page.waitForTimeout(400);
  const finalState = await page.locator("#debug-state").textContent() ?? "";
  console.log("FINAL_STATE:", finalState);

  // If SPACE only closed the overlay, the hero is still in the dungeon.
  expect(finalState, "hero should remain in the dungeon after merely closing the save menu")
    .toContain("[DUNGEON:heartlands_dungeon]");
});

