import { expect, test, type Page } from "@playwright/test";

async function waitForState(page: Page, text: string): Promise<void> {
  await expect(page.locator("#debug-state")).toContainText(text);
}

async function openSaveMenu(page: Page): Promise<void> {
  await page.keyboard.press("Escape");
  await waitForState(page, "[MENU]");
  for (let i = 0; i < 12; i += 1) {
    const s = await page.locator("#debug-state").textContent() ?? "";
    if (s.includes("[MENU_SELECTION:save]")) break;
    await page.keyboard.press("ArrowDown");
    await page.waitForTimeout(80);
  }
  await waitForState(page, "[MENU_SELECTION:save]");
  await page.keyboard.press("Enter");
  await waitForState(page, "[SAVE_SLOTS:save]");
}

async function tap(page: Page, code: string): Promise<void> {
  await page.keyboard.down(code);
  await page.waitForTimeout(60);
  await page.keyboard.up(code);
  await page.waitForTimeout(350);
}

test("feature keys Y/E over the Overworld save menu", async ({ page }) => {
  await page.addInitScript(() => {
    if (!sessionStorage.getItem("tmpFeat2")) {
      localStorage.clear();
      sessionStorage.setItem("tmpFeat2", "true");
    }
  });
  await page.goto("game.html", { waitUntil: "networkidle" });
  await page.evaluate(async () => {
    const save = await import("/2dnd/src/systems/save.ts");
    const player = await import("/2dnd/src/systems/player.ts");
    const codex = await import("/2dnd/src/systems/codex.ts");
    const weather = await import("/2dnd/src/systems/weather.ts");
    const stats = {
      strength: 10, dexterity: 10, constitution: 10,
      intelligence: 10, wisdom: 10, charisma: 10,
    };
    save.deleteAllSaveSlots();
    const hero = player.createPlayer("Feat Hero", stats, "knight");
    hero.progression.pendingCutsceneIds = [];
    hero.progression.pendingFeatureRevealIds = [];
    hero.progression.tutorial.completed = true;
    hero.progression.discoveredFeatureIds = ["achievements", "equipment"];
    save.saveGame(
      hero, new Set(), codex.createCodex(), hero.appearanceId, 0,
      weather.createWeatherState(),
    );
  });
  await page.reload({ waitUntil: "networkidle" });
  await waitForState(page, "BOOT | Screen: title");
  await page.keyboard.press("Space");
  await waitForState(page, "OVERWORLD");

  await openSaveMenu(page);
  await tap(page, "KeyY");
  const afterY = await page.locator("#debug-state").textContent() ?? "";
  console.log("Y_ACHIEVEMENTS_OPEN:", afterY.includes("[ACHIEVEMENTS") ? "YES" : "no");
  console.log("Y_SAVE_OPEN:", afterY.includes("[SAVE_SLOTS:") ? "yes" : "no");

  // Ensure the save menu is open for the E test.
  const stillOpen = (await page.locator("#debug-state").textContent() ?? "").includes("[SAVE_SLOTS:");
  if (!stillOpen) await openSaveMenu(page);
  await tap(page, "KeyE");
  const afterE = await page.locator("#debug-state").textContent() ?? "";
  console.log("E_MENU_TAG:", /\[MENU\]/.test(afterE) ? "YES (equip/menu overlay open)" : "no");
  console.log("E_SAVE_OPEN:", afterE.includes("[SAVE_SLOTS:") ? "yes" : "no");
  console.log("E_FULL:", afterE.slice(0, 160));
  expect(true).toBe(true);
});

